import {money,createMessage,whatsappLink,safeHttp,initializeBackend,isAuthenticated,login,logout,refreshData} from './store.js';
import {e,icon,toast,modal,submit,field,area,empty} from './ui.js';
import {booking,cartModal,productDetail,initFlows,getCartCount,addToCart} from './flows.js';
import {renderAdmin,bindAdmin} from './admin.js';
let data,recovery=false;
try{data=await initializeBackend();}catch{document.getElementById('app').innerHTML='<main class="container section"><h1>Não foi possível conectar ao site</h1><p>Atualize a página em alguns instantes. Nenhum dado será salvo enquanto o servidor estiver indisponível.</p><button class="btn primary" id="retry">Tentar novamente</button></main>';document.getElementById('retry').onclick=()=>location.reload();throw new Error('Backend indisponível.');}
const app=document.getElementById('app');
const ctx={getData:()=>data,render,booking,toast,isRecovery:()=>recovery,setRecovery:v=>{recovery=v;}};
initFlows(ctx);
const services=()=>data.services.filter(s=>s.active),products=()=>data.products.filter(p=>p.active);
function brand(){const c=data.content;return `<a class="brand" href="#/" aria-label="${e(c.brand)} · Início"><img src="${e(c.logo||'assets/logo.jpeg')}" alt="Logo ${e(c.brand)}" width="60" height="60"><div><div class="brand-name">${e(c.brand)}</div><small>${e(c.tagline)}</small></div></a>`;}
function header(shop=false){const c=data.content;return `<div class="announcement">${e(c.announcement)}</div><header class="header"><div class="container nav">${brand()}<nav class="nav-links" aria-label="Navegação principal"><a class="${shop?'':'active'}" href="#/">${e(c.navHome)}</a><a href="#services">${e(c.navServices)}</a><a href="#about">${e(c.navAbout)}</a><a class="${shop?'active':''}" href="#/loja">${e(c.navShop)}</a><a href="#contact">${e(c.navContact)}</a></nav><div class="nav-actions"><button class="icon-btn" data-cart aria-label="Abrir carrinho">${icon('bag')}${getCartCount()?`<span class="count">${getCartCount()}</span>`:''}</button><button class="btn primary small" data-book>${icon('calendar')}${e(c.bookLabel)}</button><button class="icon-btn menu-toggle" aria-label="Abrir menu" aria-expanded="false">${icon('menu')}</button></div></div></header>`;}
function instagram(){const v=data.content.instagram.trim();if(!v)return '';if(safeHttp(v))return ['instagram.com','www.instagram.com'].includes(new URL(v).hostname)?v:'';return /^@?[\w.]+$/.test(v)?`https://www.instagram.com/${v.replace(/^@/,'')}/`:'';}
function footer(){const c=data.content;return `<footer class="footer"><div class="container"><div class="footer-top"><div>${brand()}<p>${e(c.footerDescription)}</p></div><div class="footer-links"><a href="#services">${e(c.navServices)}</a><a href="#/loja">${e(c.navShop)}</a><a href="#contact">${e(c.navContact)}</a>${instagram()?`<a href="${e(instagram())}" target="_blank" rel="noopener noreferrer">${icon('instagram')}<span class="visually-hidden">Instagram</span></a>`:''}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} ${e(c.footerCopyright)}</span><button class="footer-admin" data-admin>${icon('settings')} ${e(c.adminLinkLabel)}</button></div></div></footer><button class="floating-wa" data-whatsapp aria-label="Conversar pelo WhatsApp">${icon('whatsapp')}</button>`;}
function serviceCard(s,i){const c=data.content;return `<article class="service-card">${s.image?`<img class="service-photo" src="${e(s.image)}" alt="${e(s.title)}" loading="lazy">`:`<div class="service-icon">${icon(['foot','shield','heart','leaf'][i%4])}</div>`}<div class="category">${e(s.category)}</div><h3>${e(s.title)}</h3><p>${e(s.description)}</p><div class="meta"><span>${icon('clock')}${s.duration} min</span><strong>${money(s.price)}</strong></div><button class="text-btn" data-book="${e(s.id)}">${e(c.serviceLink)}</button></article>`;}
function productCard(p,i){return `<article class="product-card"><button class="product-image product-open" data-product="${e(p.id)}" aria-label="Ver ${e(p.title)}">${p.image?`<img src="${e(p.image)}" alt="${e(p.title)}" loading="lazy" width="300" height="300">`:icon('box')}${p.stock===0?'<span class="product-badge">Esgotado</span>':i===0?'<span class="product-badge">Cuidado essencial</span>':''}</button><p class="product-category">${e(p.category)}</p><h3><button class="plain product-name" data-product="${e(p.id)}">${e(p.title)}</button></h3><div class="product-bottom"><strong>${money(p.price)}</strong><button data-add="${e(p.id)}" aria-label="Adicionar ${e(p.title)} ao carrinho" ${p.stock===0?'disabled':''}>${icon('plus')}</button></div></article>`;}
function sectionHead(eyebrow,title,desc){return `<div class="section-head"><div><div class="eyebrow">${e(eyebrow)}</div><h2>${e(title)}</h2></div><p class="section-desc">${e(desc)}</p></div>`;}
function home(){const c=data.content;return `${header()}<main id="main"><section class="hero"><div class="container hero-grid"><div><div class="eyebrow">${e(c.heroEyebrow)}</div><h1>${e(c.heroTitle)}</h1><p class="lead">${e(c.heroDescription)}</p><div class="hero-buttons"><button class="btn primary" data-book>${icon('calendar')}${e(c.bookLabel)}</button><a class="btn secondary" href="#/loja">${e(c.shopLabel)}</a></div><div class="hero-reassurance">${icon('shield')} ${e(c.heroReassurance)}</div></div><div class="hero-art">${c.heroImage?`<img src="${e(c.heroImage)}" alt="${e(c.heroImageAlt)}" width="560" height="490" fetchpriority="high">`:`<img class="hero-logo" src="${e(c.logo)}" alt="${e(c.brand)}">`}<div class="hero-tag">${icon('leaf')} ${e(c.heroTag)}</div><div class="hero-badge"><div class="badge-icon">${icon('heart')}</div><div><strong>${e(c.heroBadgeTitle)}</strong><small>${e(c.heroBadgeText)}</small></div></div></div></div></section><div class="benefits"><div class="container benefits-inner">${[['heart',c.benefit1],['leaf',c.benefit2],['shield',c.benefit3]].map(([i,t])=>`<div class="benefit">${icon(i)}${e(t)}</div>`).join('')}</div></div><section class="section" id="services"><div class="container">${sectionHead(c.serviceEyebrow,c.serviceTitle,c.serviceDescription)}<div class="cards">${services().map(serviceCard).join('')}</div>${services().length?'':empty('Os tratamentos serão publicados em breve.','leaf')}</div></section><section class="section about" id="about"><div class="container about-grid"><div class="about-visual"><img class="${c.aboutImage?'':'fallback'}" src="${e(c.aboutImage||c.logo)}" alt="${e(c.aboutImageAlt)}" loading="lazy" width="550" height="440"><div class="about-label"><strong>${e(c.specialist)}</strong><p>${e(c.qualification)}</p></div></div><div class="about-copy"><div class="eyebrow">${e(c.aboutEyebrow)}</div><h2>${e(c.aboutTitle)}</h2><p>${e(c.aboutDescription)}</p><div class="pills"><span class="pill">${icon('check')}${e(c.aboutPill1)}</span><span class="pill">${icon('check')}${e(c.aboutPill2)}</span></div><button class="btn primary" data-book>${e(c.bookLabel)}</button></div></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="eyebrow">${e(c.shopEyebrow)}</div><h2>${e(c.shopTitle)}</h2><p class="section-desc spacer">${e(c.shopDescription)}</p></div><a class="text-btn" href="#/loja">${e(c.shopButton)}</a></div><div class="cards">${products().slice(0,4).map(productCard).join('')}</div>${products().length?'':empty('Nossa seleção de produtos estará disponível em breve.','bag')}</div></section><section class="container"><div class="banner"><div><h2>${e(c.bookingTitle)}</h2><p>${e(c.bookingDescription)}</p></div><button class="btn white" data-book>${icon('calendar')}${e(c.bookLabel)}</button></div></section>${contact()}</main>${footer()}`;}
function contact(){const c=data.content;return `<section class="section" id="contact"><div class="container contact-grid"><div class="contact-copy"><div class="eyebrow">${e(c.contactEyebrow)}</div><h2>${e(c.contactTitle)}</h2><p>${e(c.contactDescription)}</p><div class="contact-detail">${icon('pin')}<div><strong>${e(c.contactOfficeLabel)}</strong><span>${e(c.address)}</span></div></div><div class="contact-detail">${icon('clock')}<div><strong>${e(c.contactHoursLabel)}</strong><span>${e(c.hours)}</span></div></div>${c.phone?`<div class="contact-detail">${icon('whatsapp')}<div><strong>WhatsApp</strong><button class="text-btn" data-whatsapp>${e(c.phone)}</button></div></div>`:''}${c.email?`<div class="contact-detail">${icon('mail')}<div><strong>E-mail</strong><a href="mailto:${e(c.email)}">${e(c.email)}</a></div></div>`:''}${instagram()?`<a class="text-btn" href="${e(instagram())}" target="_blank" rel="noopener noreferrer">${icon('instagram')} ${e(c.socialLabel)}</a>`:''}<div class="map-placeholder">${icon('pin')}<div><strong>${e(c.mapTitle)}</strong><p>${e(c.address)}</p></div>${c.address&&c.address!=='Endereço do consultório a cadastrar'?`<a class="btn secondary small" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(c.address)}" target="_blank" rel="noopener noreferrer">${e(c.mapButton)}</a>`:''}</div></div><form class="contact-form" id="contact-form"><h3>${e(c.contactFormTitle)}</h3>${field('name',c.contactNameLabel,'','text','required minlength="2" maxlength="120" autocomplete="name" placeholder="Como podemos chamar você?"')}${field('email',c.contactEmailLabel,'','email','required maxlength="160" autocomplete="email" placeholder="seu@email.com"')}${area('message',c.contactMessageLabel,'','required minlength="5" maxlength="3000" placeholder="Conte como podemos ajudar…"')}<label class="checkbox-label"><input type="checkbox" name="consent" required>${e(c.contactConsent)}</label><button type="submit" class="btn primary full">${e(c.contactSubmitLabel)}</button><p class="hint spacer">${e(c.contactPrivacy)}</p></form></div></section>`;}
let shopCategory='Todos',shopQuery='';
function shop(){const c=data.content;const categories=['Todos',...new Set(products().map(p=>p.category).filter(Boolean))];const filtered=products().filter(p=>(shopCategory==='Todos'||p.category===shopCategory)&&`${p.title} ${p.description}`.toLocaleLowerCase('pt-BR').includes(shopQuery.toLocaleLowerCase('pt-BR')));return `${header(true)}<main id="main"><div class="page-hero"><div class="container"><div class="eyebrow">${e(c.shopEyebrow)}</div><h1 class="page-title">${e(c.shopTitle)}</h1><p>${e(c.shopDescription)}</p></div></div><section class="section"><div class="container"><div class="shop-tools"><div class="chips" role="group" aria-label="Categorias">${categories.map(t=>`<button class="chip ${shopCategory===t?'active':''}" data-category="${e(t)}" aria-pressed="${shopCategory===t}">${e(t)}</button>`).join('')}</div><label class="visually-hidden" for="shop-search">Buscar produtos</label><input id="shop-search" type="search" value="${e(shopQuery)}" placeholder="Buscar um produto…" maxlength="100"></div><div class="cards">${filtered.map(productCard).join('')}</div>${filtered.length?'':empty('Nenhum produto encontrado. Tente outra busca.','search')}</div></section></main>${footer()}`;}
function route(){return location.hash.startsWith('#/admin')?'admin':location.hash.startsWith('#/loja')?'shop':'home';}
function applyColor(hex){document.documentElement.style.setProperty('--accent',hex);const channels=hex.slice(1).match(/../g).map(x=>parseInt(x,16));document.documentElement.style.setProperty('--on-accent',channels[0]*.299+channels[1]*.587+channels[2]*.114>155?'#183b35':'#fff');}
function render(){applyColor(data.content.accent);document.title=`${data.content.brand} · Podologia & bem-estar`;const r=route();if(r==='admin'&&!isAuthenticated()){app.innerHTML=`<main class="container section"><a href="#/">Voltar ao site</a><section class="panel panel-body" style="max-width:440px;margin:40px auto"><h1>Entrar no painel</h1><form id="login-form">${field('username','Usuário','','text','required autocomplete="username" maxlength="120"')}${field('password','Senha','','password','required autocomplete="current-password" maxlength="256"')}<button class="btn primary" type="submit">Entrar</button></form></section></main>`;submit(app.querySelector('#login-form'),async v=>{await login(v.username,v.password);});return;}app.innerHTML=r==='admin'?renderAdmin(ctx):r==='shop'?shop():home();if(r==='admin'){bindAdmin(ctx);app.querySelector('[data-logout]').onclick=async()=>{try{await logout();}catch(err){toast(err.message);}};}else bindPublic();}
function bindPublic(){
  app.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>booking(b.dataset.book||''));app.querySelectorAll('[data-cart]').forEach(b=>b.onclick=cartModal);app.querySelectorAll('[data-admin]').forEach(b=>b.onclick=()=>{location.hash='#/admin';});app.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>productDetail(b.dataset.product));app.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>addToCart(b.dataset.add));
  app.querySelectorAll('[data-whatsapp]').forEach(b=>b.onclick=()=>{const href=whatsappLink(data.content.phone,`Olá! Gostaria de saber mais sobre os cuidados da ${data.content.brand}.`);if(href)window.open(href,'_blank','noopener,noreferrer');else {const el=modal('Vamos conversar','<p>O WhatsApp do consultório ainda não foi cadastrado. Você pode deixar uma mensagem no formulário de contato.</p><p class="hint spacer">Profissional: cadastre seu número com código do país em Painel → Conteúdo e marca → Contatos.</p>','<a class="btn primary" href="#contact" data-contact-link>Ir para o contato</a>');el.querySelector('[data-contact-link]').onclick=()=>el.close();}});
  const toggle=app.querySelector('.menu-toggle');if(toggle)toggle.onclick=()=>{const open=app.querySelector('.nav-links').classList.toggle('open');toggle.setAttribute('aria-expanded',open);toggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');};
  app.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{shopCategory=b.dataset.category;render();});const search=app.querySelector('#shop-search');if(search)search.oninput=()=>{shopQuery=search.value;render();app.querySelector('#shop-search').focus();};
  const form=app.querySelector('#contact-form');if(form)submit(form,async v=>{await createMessage({name:v.name.trim(),email:v.email.trim(),message:v.message.trim(),consent:v.consent==='on'});toast('Mensagem registrada. Obrigado por entrar em contato!');});
}
globalThis.addEventListener('babe:data',ev=>{data=ev.detail;recovery=false;render();});
globalThis.addEventListener('babe:refresh-error',()=>toast('Registro confirmado. Atualize a página para consultar os dados mais recentes.'));
globalThis.addEventListener('focus',()=>{if(!document.querySelector('dialog[open]')&&!app.querySelector('form :focus'))refreshData().catch(()=>toast('Não foi possível atualizar os dados.'));});
globalThis.addEventListener('hashchange',()=>{document.getElementById('modal').close();render();requestAnimationFrame(()=>{const target=['#services','#about','#contact'].includes(location.hash)?document.querySelector(location.hash):null;target?target.scrollIntoView({block:'start'}):window.scrollTo({top:0});});});
document.addEventListener('error',ev=>{if(ev.target instanceof HTMLImageElement){ev.target.style.visibility='hidden';ev.target.parentElement.classList.add('image-unavailable');}},true);
render();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'list_care_catalog',title:'Ver tratamentos e produtos',description:'Retorna os tratamentos e produtos ativos deste navegador, com preços e estoque. Não altera dados.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(!input||Object.keys(input).length)throw new Error('Nenhum parâmetro é aceito.');return {services:services().map(({id,title,duration,price})=>({id,title,duration,price})),products:products().map(({id,title,stock,price})=>({id,title,stock,price}))};}},{name:'start_care_booking',title:'Iniciar agendamento',description:'Abre o fluxo de agendamento. O cliente revisa e confirma pela interface. Não cria um agendamento.',inputSchema:{type:'object',properties:{serviceId:{type:'string'}},required:['serviceId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||Object.keys(input).length!==1||!services().some(s=>s.id===input.serviceId))throw new Error('Tratamento não encontrado.');booking(input.serviceId);return {opened:true,serviceId:input.serviceId};}}];for(const t of tools)try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}globalThis.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
